lessons.example:
scope = {
  'approved_targets': ['training.example'],
  'stop_condition': 'unexpected service impact'
}
# This records permission boundaries; it does not contact a system.

access_policy = {
  'payroll': ['finance_group'],
  'audit_log': True
}
# Least privilege supports confidentiality and accountability.

CREATE DATABASE IF NOT EXISTS LEARNING_DB;
CREATE SCHEMA IF NOT EXISTS LEARNING_DB.RAW;
CREATE TABLE IF NOT EXISTS LEARNING_DB.RAW.ORDERS (
  order_id NUMBER,
  order_date DATE,
  customer_name VARCHAR,
  amount NUMBER(10, 2)
);

SELECT order_id, amount
FROM LEARNING_DB.RAW.ORDERS
WHERE amount >= 100;

CREATE FILE FORMAT learning_csv
  TYPE = CSV
  SKIP_HEADER = 1
  FIELD_OPTIONALLY_ENCLOSED_BY = '"';

CREATE STAGE learning_stage
  FILE_FORMAT = learning_csv;

COPY INTO LEARNING_DB.RAW.ORDERS
FROM @learning_stage
ON_ERROR = 'ABORT_STATEMENT';
